#!/usr/bin/env node
/**
 * Bundles TradingView Lightweight Charts v5 + @institutional-ea/chart-core
 * into a self-contained offline JS string (src/generated/chartBundle.ts)
 * for react-native-webview with ZERO CDN requests at runtime.
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const mobileRoot = path.resolve(__dirname, "..");
const repoRoot = path.resolve(mobileRoot, "../..");
const require = createRequire(import.meta.url);

// Resolve esbuild from companion/node_modules or root node_modules
const esbuildPath = fs.existsSync(path.join(repoRoot, "companion/node_modules/esbuild"))
  ? path.join(repoRoot, "companion/node_modules/esbuild")
  : path.join(repoRoot, "node_modules/esbuild");
const esbuild = require(esbuildPath);

const entryFile = path.join(mobileRoot, "src/chart-webview/chartEntry.ts");
const outDir = path.join(mobileRoot, "src/generated");
const outFile = path.join(outDir, "chartBundle.ts");

const result = await esbuild.build({
  entryPoints: [entryFile],
  bundle: true,
  minify: true,
  format: "iife",
  target: ["chrome64", "safari13"], // Compatible with Android 7 (API 24+) WebView
  write: false,
  nodePaths: [
    path.join(repoRoot, "companion/node_modules"),
    path.join(repoRoot, "node_modules"),
    path.join(mobileRoot, "node_modules"),
  ],
  alias: {
    "@institutional-ea/chart-core": path.join(repoRoot, "packages/chart-core/src/index.ts"),
  },
});

const bundledJs = result.outputFiles[0].text;
// Escape </script> defensively so inline <script> injection can never terminate early
const safeJs = bundledJs.replace(/<\/script/gi, "<\\/script");

fs.mkdirSync(outDir, { recursive: true });
const tsOutput = `// AUTO-GENERATED by scripts/build-chart-bundle.mjs — DO NOT EDIT MANUALLY
// Contains offline TradingView Lightweight Charts v5 + @institutional-ea/chart-core (${(safeJs.length / 1024).toFixed(1)} KB)
export const CHART_WEBVIEW_BUNDLE_JS: string = ${JSON.stringify(safeJs)};
`;

fs.writeFileSync(outFile, tsOutput, "utf8");
console.log(
  `[build-chart-bundle] Wrote ${path.relative(repoRoot, outFile)} (${(safeJs.length / 1024).toFixed(1)} KB minified)`
);
